        self.assertEqual(low_stock(items), ["alpha", "zinc"])

    def test_low_stock_threshold_can_be_overridden(self):
        with patch.dict(os.environ, {"LOW_STOCK_THRESHOLD": "20"}):
            self.assertEqual(low_stock([{"name": "part", "quantity": 19}]), ["part"])


